CREATE TABLE IF NOT EXISTS demo_session_issuance (ip_hash TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_demo_session_issuance_created ON demo_session_issuance(created_at);
CREATE TABLE IF NOT EXISTS demo_sessions (token_hash TEXT PRIMARY KEY, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, expires_at TEXT NOT NULL, last_seen_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_demo_sessions_expiry ON demo_sessions(expires_at);
CREATE TABLE IF NOT EXISTS demo_session_records (token_hash TEXT NOT NULL REFERENCES demo_sessions(token_hash) ON DELETE CASCADE, record_id TEXT NOT NULL, module TEXT NOT NULL, action TEXT NOT NULL CHECK(action IN ('upsert','delete')), title TEXT, status TEXT, amount_cents INTEGER, payload_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(token_hash, record_id), CHECK(length(record_id) BETWEEN 8 AND 80), CHECK(length(module) BETWEEN 2 AND 32));
CREATE INDEX IF NOT EXISTS idx_demo_session_records_module ON demo_session_records(token_hash, module, updated_at);
